def transform(grid):
    candidates=[]
    for r in range(len(grid)-2):
        for c in range(len(grid[0])-2):
            block=[row[c:c+3] for row in grid[r:r+3]]
            if all(x != 0 for row in block for x in row):
                colors={x for row in block for x in row}
                candidates.append((len(colors),r,c,block))
    return max(candidates, key=lambda x:x[0])[3]
